def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def rectangle(r, c):
        if not (0 <= r < h and 0 <= c < w) or grid[r][c] in (0, 5):
            return None
        left = right = c
        while left > 0 and grid[r][left - 1] not in (0, 5):
            left -= 1
        while right + 1 < w and grid[r][right + 1] not in (0, 5):
            right += 1

        top = bottom = r
        while top > 0 and all(grid[top - 1][x] not in (0, 5)
                              for x in range(left, right + 1)):
            top -= 1
        while bottom + 1 < h and all(grid[bottom + 1][x] not in (0, 5)
                                     for x in range(left, right + 1)):
            bottom += 1
        return top, bottom, left, right

    # Vertical 5-lines: repeat the adjacent tile along the line.
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1
                continue
            start = r
            while r + 1 < h and grid[r + 1][c] == 5:
                r += 1
            end = r
            if end > start:
                for endpoint in (start, end):
                    for side in (-1, 1):
                        sc = c + side
                        rect = rectangle(endpoint, sc)
                        if rect is None:
                            continue
                        top, bottom, left, right = rect
                        period = bottom - top + 1
                        for rr in range(start, end + 1):
                            if endpoint == start:
                                sr = top + ((rr - start) % period)
                            else:
                                sr = bottom - ((end - rr) % period)
                            for cc in range(left, right + 1):
                                out[rr][cc] = grid[sr][cc]
                        break
                    else:
                        continue
                    break
            r += 1

    # Horizontal 5-lines: repeat the adjacent tile along the line.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1
                continue
            start = c
            while c + 1 < w and grid[r][c + 1] == 5:
                c += 1
            end = c
            if end > start:
                for endpoint in (start, end):
                    for side in (-1, 1):
                        sr = r + side
                        rect = rectangle(sr, endpoint)
                        if rect is None:
                            continue
                        top, bottom, left, right = rect
                        period = right - left + 1
                        for cc in range(start, end + 1):
                            if endpoint == start:
                                source_c = left + ((cc - start) % period)
                            else:
                                source_c = right - ((end - cc) % period)
                            for rr in range(top, bottom + 1):
                                out[rr][cc] = grid[rr][source_c]
                        break
                    else:
                        continue
                    break
            c += 1

    return out
